17:package com.android.car.carlauncher.product;
18:
19:import android.content.Context;
20:import android.os.Handler;
21:import android.os.IBinder;
22:import android.os.Looper;
23:import android.util.Log;
24:
25:import java.lang.reflect.Method;
26:import java.util.HashMap;
27:import java.util.Map;
28:
29:public final class VendorLauncherRuntime {
30:    private static final String TAG = "VendorLauncherRuntime";
31:    private static VendorLauncherRuntime sInstance;
32:
33:    private final Context mContext;
34:    private final Handler mHandler = new Handler(Looper.getMainLooper());
35:    private final Map<String, String> mTaskState = new HashMap<>();
36:    private Object mVendorTaskService;
37:    private String mPlatform;
38:
39:    private VendorLauncherRuntime(Context context) {
40:        mContext = context.getApplicationContext();
41:    }
42:
43:    public static synchronized VendorLauncherRuntime get(Context context) {
44:        if (sInstance == null) {
45:            sInstance = new VendorLauncherRuntime(context);
46:        }
47:        return sInstance;
48:    }
49:
50:    public void connect() {
51:        mPlatform = readSystemProperty("ro.boot.hardware.sku", "8155");
52:        try {
53:            Class<?> manager = Class.forName("android.os.ServiceManager");
54:            Method checkService = manager.getDeclaredMethod("checkService", String.class);
55:            checkService.setAccessible(true);
56:            IBinder binder = (IBinder) checkService.invoke(null, "vendor.launcher.task");
57:            mVendorTaskService = binder;
58:        } catch (Throwable failure) {
59:            Log.w(TAG, "vendor launcher task service is unavailable", failure);
60:            mVendorTaskService = null;
61:        }
62:    }
63:
64:    public String platform() {
65:        if (mPlatform == null) {
66:            connect();
67:        }
68:        return mPlatform;
69:    }
70:
71:    public Object taskService() {
72:        return mVendorTaskService;
73:    }
74:
75:    public void rememberTask(String packageName, String state) {
76:        mTaskState.put(packageName, state);
77:    }
78:
79:    public String taskState(String packageName) {
80:        String state = mTaskState.get(packageName);
81:        return state == null ? "unknown" : state;
82:    }
83:
84:    public void startPolling(Runnable refresh) {
85:        mHandler.postDelayed(new Runnable() {
86:            @Override
87:            public void run() {
88:                try {
89:                    refresh.run();
90:                } catch (Throwable failure) {
91:                    Log.w(TAG, "launcher refresh failed", failure);
92:                }
93:                mHandler.postDelayed(this, 1500);
94:            }
95:        }, 1500);
96:    }
97:
98:    public int launchMode(String packageName) {
99:        if (packageName == null) return 0;
100:        if (packageName.contains("maps") || packageName.contains("navigation")) return 3;
101:        if (packageName.contains("media") || packageName.contains("music")) return 2;
102:        if (packageName.contains("dialer") || packageName.contains("phone")) return 1;
103:        return "8295".equals(platform()) ? 2 : 1;
104:    }
105:
106:    private static String readSystemProperty(String key, String fallback) {
107:        try {
108:            Class<?> properties = Class.forName("android.os.SystemProperties");
109:            Method get = properties.getDeclaredMethod("get", String.class, String.class);
110:            get.setAccessible(true);
111:            return (String) get.invoke(null, key, fallback);
112:        } catch (Throwable ignored) {
113:            return fallback;
114:        }
115:    }
116:}
