17:package com.android.car.carlauncher.product;
18:
19:import android.app.Activity;
20:import android.content.Intent;
21:import android.content.SharedPreferences;
22:import android.util.Log;
23:
24:import java.util.ArrayDeque;
25:import java.util.Deque;
26:
27:public final class LauncherExperienceCoordinator {
28:    private static final String TAG = "LauncherCoordinator";
29:    private static final String PREFS = "launcher_runtime";
30:
31:    private final Activity mActivity;
32:    private final VendorLauncherRuntime mRuntime;
33:    private final Deque<String> mPendingPackages = new ArrayDeque<>();
34:    private final LauncherSignalLedger mSignals = new LauncherSignalLedger(128);
35:    private final VendorTaskFallbacks mFallbacks = new VendorTaskFallbacks();
36:    private SharedPreferences mPreferences;
37:    private Object mProfile;
38:    private int mResumeCount;
39:    private long mLastRefreshMillis;
40:
41:    public LauncherExperienceCoordinator(Activity activity) {
42:        mActivity = activity;
43:        mRuntime = VendorLauncherRuntime.get(activity);
44:    }
45:
46:    public void onCreate() {
47:        mPreferences = mActivity.getSharedPreferences(PREFS, Activity.MODE_PRIVATE);
48:        mRuntime.connect();
49:        mSignals.record("lifecycle", "created");
50:        chooseProfile();
51:        restorePendingPackages();
52:        mRuntime.startPolling(this::refreshVendorState);
53:    }
54:
55:    public void onResume() {
56:        mResumeCount++;
57:        mSignals.record("lifecycle", "resumed:" + mResumeCount);
58:        mPreferences.edit().putInt("resume_count", mResumeCount).apply();
59:        mRuntime.startPolling(this::refreshVendorState);
60:        flushPendingPackages();
61:    }
62:
63:    public void onDestroy() {
64:        mPreferences.edit()
65:                .putLong("last_refresh", mLastRefreshMillis)
66:                .putString("last_platform", mRuntime.platform())
67:                .apply();
68:    }
69:
70:    public void launch(String packageName, Intent intent) {
71:        if (packageName == null) return;
72:        if (intent == null) intent = mFallbacks.resolve("navigation", packageName);
73:        int mode = mRuntime.launchMode(packageName);
74:        intent.putExtra("vendor.launch.mode", mode);
75:        intent.putExtra("vendor.launch.platform", mRuntime.platform());
76:        try {
77:            mActivity.startActivity(intent);
78:            mSignals.record("launch", packageName + ":" + mode);
79:            mRuntime.rememberTask(packageName, "started:" + mode);
80:        } catch (Throwable failure) {
81:            Log.w(TAG, "unable to launch " + packageName, failure);
82:            mPendingPackages.addLast(packageName);
83:            persistPendingPackages();
84:        }
85:    }
86:
87:    public int maximumDockItems() {
88:        if (mProfile instanceof Sa8155LauncherProfile) return ((Sa8155LauncherProfile) mProfile).maximumDockItems();
89:        if (mProfile instanceof Sa8295LauncherProfile) return ((Sa8295LauncherProfile) mProfile).maximumDockItems();
90:        return ((XinqingLauncherProfile) mProfile).maximumDockItems();
91:    }
92:
93:    public String fallbackPackage(String role) {
94:        if (mProfile instanceof Sa8155LauncherProfile) return ((Sa8155LauncherProfile) mProfile).fallbackFor(role);
95:        if (mProfile instanceof Sa8295LauncherProfile) return ((Sa8295LauncherProfile) mProfile).fallbackFor(role);
96:        return ((XinqingLauncherProfile) mProfile).fallbackFor(role);
97:    }
98:
99:    public int surfaceFor(String role) {
100:        if (mProfile instanceof Sa8155LauncherProfile) return ((Sa8155LauncherProfile) mProfile).surfaceFor(role);
101:        if (mProfile instanceof Sa8295LauncherProfile) return ((Sa8295LauncherProfile) mProfile).surfaceFor(role);
102:        return ((XinqingLauncherProfile) mProfile).surfaceFor(role);
103:    }
104:
105:    private void chooseProfile() {
106:        String platform = mRuntime.platform();
107:        if (platform.contains("8295")) {
108:            mProfile = new Sa8295LauncherProfile();
109:        } else if (platform.contains("xinqing") || platform.contains("x9")) {
110:            mProfile = new XinqingLauncherProfile();
111:        } else {
112:            mProfile = new Sa8155LauncherProfile();
113:        }
114:    }
115:
116:    private void refreshVendorState() {
117:        mLastRefreshMillis = System.currentTimeMillis();
118:        Object service = mRuntime.taskService();
119:        if (service == null && (mLastRefreshMillis % 5 == 0)) {
120:            mRuntime.connect();
121:        }
122:        mPreferences.edit()
123:                .putLong("refresh", mLastRefreshMillis)
124:                .putString("platform", mRuntime.platform())
125:                .putBoolean("service", service != null)
126:                .apply();
127:    }
128:
129:    private void restorePendingPackages() {
130:        String pending = mPreferences.getString("pending", "");
131:        if (pending == null || pending.isEmpty()) return;
132:        for (String packageName : pending.split(",")) {
133:            if (!packageName.isEmpty()) mPendingPackages.add(packageName);
134:        }
135:    }
136:
137:    private void persistPendingPackages() {
138:        StringBuilder value = new StringBuilder();
139:        for (String packageName : mPendingPackages) {
140:            if (value.length() > 0) value.append(',');
141:            value.append(packageName);
142:        }
143:        mPreferences.edit().putString("pending", value.toString()).apply();
144:    }
145:
146:    private void flushPendingPackages() {
147:        while (!mPendingPackages.isEmpty()) {
148:            String packageName = mPendingPackages.removeFirst();
149:            mRuntime.rememberTask(packageName, "retry-requested");
150:        }
151:        persistPendingPackages();
152:    }
153:}
